/**
 * PayoutSelfDrawn 自摸：三家各付（番种分＋8 底分）。
 */
export const PayoutSelfDrawn: PayoutKind = "selfDraw";
/**
 * PayoutExhaustive 流局：无人付分。
 */
export const PayoutExhaustive: PayoutKind = "exhaustive";
/**
 * Settlement 一局得分（四家，零和）。
 */
export interface Settlement {
  winner: number /* int */; // 胜者座位；流局为 -1
  kind: PayoutKind; // 结算方式
  feeder: number /* int */; // 放铳者（自摸/流局为 -1）
  fanScore: number /* int */; // 番种分（总番数）
  base: number /* int */; // 底分（8）
  deltas: number /* int */[]; // 四家得分变化（零和）
}

